다음 C 프로그램의 출력 값은?

#include <stdio.h>

int func(int n);
int main(void){
   int num;

   printf("%d\n", func(5));
   return 0;
}

int func(int n){
   if (n < 2)
     return n;
   else {
     int i, tmp, current=1, last=0;
     for(i=2; i<=n; i++){
        tmp = current;
        current += last;
        last = tmp;
     }
     return current;
   }
}

